// Ported from the Node app's Sequelize model ClinicVisit (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class ClinicVisitConfiguration : IEntityTypeConfiguration<ClinicVisit>
{
    public void Configure(EntityTypeBuilder<ClinicVisit> builder)
    {
        builder.ToTable("clinic_visits", t =>
        {
            t.HasCheckConstraint("CK_clinic_visits_outcome", "[outcome] IN (N'returned_to_class', N'rested', N'sent_home', N'referred')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.VisitDate).HasColumnName("visit_date").HasColumnType("date");
        builder.Property(e => e.Complaint).HasColumnName("complaint").HasColumnType("nvarchar(255)").HasMaxLength(255).IsRequired();
        builder.Property(e => e.Treatment).HasColumnName("treatment").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.Medication).HasColumnName("medication").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.Property(e => e.Outcome).HasColumnName("outcome").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'returned_to_class'");
        builder.Property(e => e.ParentInformed).HasColumnName("parent_informed");
        builder.HasOne(e => e.Student).WithMany(p => p.ClinicVisits).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
